import{_ as a,c as i,o as n,ag as r}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse('{"title":"Extensión de sincronización con el Finder","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/finder-sync.md","filePath":"es/guide/finder-sync.md","lastUpdated":1794112334000}'),o={name:"es/guide/finder-sync.md"};function s(l,e,t,c,d,h){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="extension-de-sincronizacion-con-el-finder" tabindex="-1">Extensión de sincronización con el Finder <a class="header-anchor" href="#extension-de-sincronizacion-con-el-finder" aria-label="Permalink to &quot;Extensión de sincronización con el Finder&quot;">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripción general <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;Descripción general&quot;">​</a></h2><p>La extensión de sincronización Nicasa Finder añade un botón a la barra de herramientas del Finder de macOS, lo que te permite procesar archivos de imagen rápidamente sin abrir la aplicación principal de Nicasa.</p><h3 id="funciones" tabindex="-1">Funciones <a class="header-anchor" href="#funciones" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><ul><li><strong>Optimizador de imágenes</strong>: comprime y optimiza las imágenes seleccionadas</li><li><strong>Editor de imágenes con IA</strong>: edita las imágenes seleccionadas con IA (reparar, mejorar, rellenar, etc.)</li><li><strong>Acceso rápido desde la barra de herramientas del Finder</strong></li><li><strong>Funciona con varias imágenes seleccionadas</strong></li></ul><h2 id="instalacion-y-configuracion" tabindex="-1">Instalación y configuración <a class="header-anchor" href="#instalacion-y-configuracion" aria-label="Permalink to &quot;Instalación y configuración&quot;">​</a></h2><h3 id="instalacion-desde-la-app-nicasa" tabindex="-1">Instalación desde la app Nicasa <a class="header-anchor" href="#instalacion-desde-la-app-nicasa" aria-label="Permalink to &quot;Instalación desde la app Nicasa&quot;">​</a></h3><p>La extensión de sincronización viene incluida con la app principal de Nicasa. Tras instalar la app, activa la extensión:</p><ol><li>Abre <strong>Ajustes del Sistema</strong> &gt; <strong>Extensiones</strong> &gt; <strong>Extensiones del Finder</strong></li><li>Activa <strong>Nicasa Finder Sync</strong></li></ol><h3 id="boton-de-la-barra-de-herramientas" tabindex="-1">Botón de la barra de herramientas <a class="header-anchor" href="#boton-de-la-barra-de-herramientas" aria-label="Permalink to &quot;Botón de la barra de herramientas&quot;">​</a></h3><p>Una vez activada, aparece un icono de Nicasa en la barra de herramientas del Finder.</p><p>Si no se ve:</p><ol><li>Haz clic derecho en la barra de herramientas del Finder</li><li>Selecciona <strong>Personalizar barra de herramientas…</strong></li><li>Arrastra el botón de Nicasa a su posición</li></ol><h2 id="usar-el-boton-de-la-barra-de-herramientas-del-finder" tabindex="-1">Usar el botón de la barra de herramientas del Finder <a class="header-anchor" href="#usar-el-boton-de-la-barra-de-herramientas-del-finder" aria-label="Permalink to &quot;Usar el botón de la barra de herramientas del Finder&quot;">​</a></h2><h3 id="seleccionar-archivos" tabindex="-1">Seleccionar archivos <a class="header-anchor" href="#seleccionar-archivos" aria-label="Permalink to &quot;Seleccionar archivos&quot;">​</a></h3><p>Abre el Finder y selecciona una o varias imágenes. Formatos compatibles:</p><ul><li><code>.jpg</code>, <code>.jpeg</code>, <code>.png</code>, <code>.gif</code>, <code>.bmp</code>, <code>.webp</code>, <code>.svg</code>, <code>.tiff</code>, <code>.ico</code></li></ul><h3 id="usar-el-menu" tabindex="-1">Usar el menú <a class="header-anchor" href="#usar-el-menu" aria-label="Permalink to &quot;Usar el menú&quot;">​</a></h3><p>Haz clic en el botón de Nicasa de la barra de herramientas y elige:</p><table tabindex="0"><thead><tr><th>Opción</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>Optimizador de imágenes</strong></td><td>Comprime y optimiza las imágenes seleccionadas</td></tr><tr><td><strong>Editor de imágenes con IA</strong></td><td>Abre las imágenes seleccionadas en el editor de IA de Nicasa para repararlas, mejorarlas o aplicar relleno</td></tr></tbody></table><blockquote><p>⚠️ <strong>Nota</strong>: si no hay ningún archivo seleccionado, el botón emitirá un pitido y la acción no se ejecutará.</p></blockquote><h3 id="flujo-de-trabajo" tabindex="-1">Flujo de trabajo <a class="header-anchor" href="#flujo-de-trabajo" aria-label="Permalink to &quot;Flujo de trabajo&quot;">​</a></h3><ol><li>Selecciona imágenes en el Finder</li><li>Haz clic en el botón de Nicasa de la barra de herramientas → elige la acción deseada</li><li>La app Nicasa se abrirá automáticamente y procesará las imágenes seleccionadas</li></ol><h2 id="consejos" tabindex="-1">Consejos <a class="header-anchor" href="#consejos" aria-label="Permalink to &quot;Consejos&quot;">​</a></h2><ul><li>Para obtener los mejores resultados, selecciona imágenes dentro de una carpeta a la que tengas acceso</li><li>Puedes seleccionar varios archivos a la vez</li><li>Si una imagen no se abre, comprueba que sea uno de los formatos compatibles</li><li>La extensión funciona sin problemas con el sandbox de macOS: solo tienes que autorizar el acceso la primera vez</li></ul>',25)])])}const u=a(o,[["render",s]]);export{p as __pageData,u as default};
